const config=(typeof templateConfiguration==='object'&&templateConfiguration)||{};
const bindings=Array.isArray(templateBindings)?templateBindings:[];
const event=input.event||{kind:'open',action:'',value:null,form:{}};
const action=String(event.action||'');
const esc=x=>String(x===null||x===undefined?'':x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const num=(x,d=0)=>typeof x!=='object'&&typeof x!=='boolean'&&x!==null&&x!==undefined&&x!==''&&Number.isFinite(Number(x))?Number(x):d;
const yes=x=>x===true||x==='true'||x==='on'||x===1;
const dateOk=x=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(String(x||'')))return false;const d=new Date(x+'T12:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===x;};
const day=x=>dateOk(x)?Math.round(Date.parse(String(x)+'T12:00:00Z')/86400000):NaN;
const currentDate=dateOk(config.asOf)?config.asOf:(new Date()).toISOString().slice(0,10);
const today=day(currentDate);
const until=x=>Number.isFinite(day(x))?day(x)-today:null;
const when=x=>dateOk(x)?Number(x.slice(8))+' '+['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Number(x.slice(5,7))-1]+' '+x.slice(0,4):'Not recorded';
const amount=(x,c)=>x===null||x===undefined||x===''?'Not recorded':String(c||'?')+' '+Math.round(num(x)).toString().replace(/\B(?=(\d{3})+(?!\d))/g,',');
const str=x=>String(x===null||x===undefined?'':x);
const safeURL=x=>/^https:\/\/[a-z0-9][^\s<>'"]*$/i.test(str(x))?str(x):'';
