function archiveBlock(role,id){if(!complete)return 'Complete authorized data is required to check dependencies.';const frozen=evidenceBlock(role,find(role,id)?.data||{},id);if(frozen)return frozen;if(role==='opportunities'){if(appl.some(a=>a.data.opportunityId===id)||rows('criteria').some(c=>c.data.opportunityId===id))return 'This grant call still has linked applications or eligibility checks. Resolve or archive the related records first.';}if(role==='applications'&&tasks.some(t=>t.data.applicationId===id))return 'This application has linked milestones. Reassign or archive them first.';if(role==='criteria'&&appl.some(a=>a.data.opportunityId===find('criteria',id)?.data.opportunityId&&a.data.eligibilityDecision==='Eligible'))return 'This check supports an already approved eligibility decision. Review and revise that decision before archiving.';return '';}
function openEdit(role,id,duplicate){if(!canWrite(role)){s.notice='Complete authorized data and write permission are required.';return;}const record=id?find(role,id):null;const data=JSON.parse(JSON.stringify(record?.data||{}));if(duplicate){if(role==='opportunities'){data.title=str(data.title)+' (copy)';data.deadline=null;data.verifiedAt=null;data.sourceUrl='';data.status='Watchlist';data.callId='';data.deadlineVersion='';}if(role==='applications'){data.project=str(data.project)+' (copy)';data.stage='Researching';data.eligibilityDecision='Pending';data.submittedAt=null;data.awardedAmount=null;data.awardNoticeUrl='';data.awardDate=null;}if(role==='criteria'){data.status='Unknown';data.assessedAt=null;data.reviewer='';data.evidenceUrl='';}if(role==='milestones'){data.title=str(data.title)+' (copy)';data.status='To do';data.completedAt=null;data.evidence='';}}
 if(!record){if(role==='opportunities')Object.assign(data,{status:'Watchlist',currency:'EUR',owner:''});if(role==='criteria')Object.assign(data,{opportunityId:s.opportunityId,status:'Unknown',mandatory:true});if(role==='applications')Object.assign(data,{opportunityId:s.opportunityId,stage:'Researching',eligibilityDecision:'Pending',currency:find('opportunities',s.opportunityId)?.data.currency||''});if(role==='milestones')Object.assign(data,{status:'To do'});}
 s.drawer={type:'edit',role,id:duplicate?null:id,expectedVersion:duplicate?null:record?.version??null};s.draft=data;s.menu='';}
function formInput(role,f,d){const [id,label,type,opts]=f;const value=d[id]===undefined||d[id]===null?'':d[id];if(id==='archived')return '';let html='';if(type==='select'||type.startsWith('rel:')){let options=[];if(type==='select')options=[['','Not recorded'],...(opts||'').split('|').map(x=>[x,x])];else{const linked=type.slice(4);options=[['','Select…'],...rows(linked).map(r=>[r.id,linked==='applications'?r.data.project:r.data.title])];}html='<select name="'+esc(id)+'">'+options.map(([v,l])=>'<option value="'+esc(v)+'"'+(str(v)===str(value)?' selected':'')+'>'+esc(l)+'</option>').join('')+'</select>';}
 else if(type==='textarea')html='<textarea name="'+esc(id)+'">'+esc(value)+'</textarea>';
 else if(type==='boolean')html='<select name="'+esc(id)+'"><option value="false"'+(!yes(value)?' selected':'')+'>No</option><option value="true"'+(yes(value)?' selected':'')+'>Yes</option></select>';
 else html='<input type="'+(type==='date'?'date':type==='number'?'number':type==='url'?'url':'text')+'"'+(type==='number'?' step="any" min="0"':'')+' name="'+esc(id)+'" value="'+esc(value)+'">';html=html.replace(/<(input|select|textarea) /,'<$1 data-ui-state data-action="draft:'+id+'" '+(!available[role].writable.includes(id)?'disabled ':''));return '<label class="'+(type==='textarea'||id==='sourceUrl'||id==='awardNoticeUrl'||id==='reason'||id==='evidenceUrl'?'wide':'')+'">'+esc(label)+html+'</label>';}
function drawer(){if(!s.drawer)return '';const d=s.drawer;if(d.type==='archive'){const blocked=archiveBlock(d.role,d.id);return '<div class="gp-overlay"><section class="gp-dialog" role="alertdialog" aria-modal="true"><h2>'+(blocked?'Cannot archive linked record':'Archive this record?')+'</h2><p>'+esc(blocked||'Archive prepares a reviewed soft update. The record history and audit log are retained. No linked records are deleted.')+'</p>'+notice()+'<footer>'+button('Cancel','close','gp-btn')+(blocked?'':button('Prepare archive','confirm-archive','gp-btn primary'))+'</footer></section></div>';}
const title=s.drawer.id?'Edit '+d.role.replace(/s$/,''):'New '+d.role.replace(/s$/,'');return '<div class="gp-overlay"><aside class="gp-drawer" role="dialog" aria-modal="true" aria-label="'+esc(title)+'"><div class="gp-drawerheader"><div><h2>'+esc(title)+'</h2><p>Changes require confirmation through TrialAgents.</p></div>'+button('×','close','gp-btn square',false,'Close form')+'</div>'+notice()+'<form class="gp-form" data-action="submit">'+displayCols[d.role].map(k=>fieldDefs[d.role].find(f=>f[0]===k)).filter(Boolean).map(f=>formInput(d.role,f,s.draft||{})).join('')+button(s.extra?'Hide additional fields':'Show additional fields','draft-extra','gp-btn')+(s.extra?fieldDefs[d.role].filter(f=>f[0]!=='archived'&&!displayCols[d.role].includes(f[0])).map(f=>formInput(d.role,f,s.draft||{})).join(''):'')+'<div class="gp-formfooter">'+button('Cancel','close','gp-btn')+'<button class="gp-btn primary" type="submit">Prepare review</button></div></form></aside></div>';}

function evidenceBlock(role,d,id){
 if(!complete)return 'Complete authorized data is required before changes.';
 const call=role==='opportunities'?id:d.opportunityId;
 if(['opportunities','criteria'].includes(role)&&appl.some(a=>a.data.opportunityId===call&&a.data.eligibilityDecision==='Eligible'))return 'Return linked eligibility decisions to Pending before changing their supporting evidence.';
 return '';
}

function validate(role,d,prior){for(const [key,,type,options]of fieldDefs[role]){if(type==='date'&&d[key]&&!dateOk(d[key]))return 'Enter a valid calendar date for '+key;if(type==='select'&&d[key]&&!(options||'').split('|').includes(d[key]))return 'Choose a valid option for '+key;}for(const key of ['verifiedAt','assessedAt','submittedAt','awardDate','completedAt'])if(d[key]&&day(d[key])>today)return 'Completed events cannot have a future date: '+key;if(['opportunities','applications'].includes(role)&&['amountMax','requestedAmount','awardedAmount'].some(k=>d[k]!==null&&d[k]!==undefined&&d[k]!==''&&!Number.isNaN(num(d[k],NaN)))&&!d.currency)return 'Record the currency for every amount.';if(role==='applications'&&prior&&d.currency!==prior.currency&&(num(prior.requestedAmount)>0||num(prior.awardedAmount)>0))return 'Currency cannot relabel existing application amounts.';if(prior&&['criteria','applications','milestones'].includes(role)){const k=role==='milestones'?'applicationId':'opportunityId';if(d[k]!==prior[k])return 'Existing record links cannot be changed. Create a new record.';}if(role==='criteria'&&!find('opportunities',d.opportunityId))return 'Select an existing authorized funding call.';if(role==='milestones'&&!find('applications',d.applicationId))return 'Select an existing authorized application.';if(role==='criteria'&&rows('criteria').some(r=>r.id!==s.drawer?.id&&r.data.opportunityId===d.opportunityId&&str(r.data.name).trim().toLowerCase()===str(d.name).trim().toLowerCase()))return 'A matching criterion already exists.';if(role==='opportunities'&&prior&&d.currency!==prior.currency&&(num(prior.amountMax,0)>0||appl.some(a=>a.data.opportunityId===s.drawer?.id)))return 'Currency cannot relabel existing amounts or linked applications.';if(role==='opportunities'){
 if(!str(d.title).trim()||!str(d.funder).trim())return 'Provide an opportunity name and funder.';
 if(d.sourceUrl&&!safeURL(d.sourceUrl))return 'Enter a valid HTTPS official source URL.';
 if(d.amountMax!==null&&d.amountMax!==undefined&&d.amountMax!==''&&num(d.amountMax,-1)<0)return 'Maximum grant amount cannot be negative.';
 if(d.status==='Open'&&(!dateOk(d.deadline)||!dateOk(d.verifiedAt)||day(d.verifiedAt)>today||!safeURL(d.sourceUrl)))return 'An open call needs an official HTTPS source, a nonfuture verification date and valid deadline.';
 if(prior&&dateOk(prior.deadline)&&str(prior.deadline)!==str(d.deadline)&&(!str(d.deadlineVersion).trim()||str(prior.deadlineVersion)===str(d.deadlineVersion)||!dateOk(d.verifiedAt)))return 'For a changed deadline, record a new official notice version and verification date.';
 }if(role==='criteria'){
 if(!str(d.name).trim()||!str(d.opportunityId).trim())return 'Select a call and enter a criterion.';
 if(d.status==='Yes'||d.status==='No'){if(!str(d.reviewer).trim()||!dateOk(d.assessedAt)||!safeURL(d.evidenceUrl)||!str(d.reason).trim())return 'A Yes/No assessment needs reviewer, date, HTTPS evidence and rationale.';}
 }if(role==='applications'){
 if(!str(d.project).trim()||!str(d.opportunityId).trim())return 'Enter the project and select a funding call.';
 const selected=find('opportunities',d.opportunityId);if(!selected)return 'The funding call is missing or inaccessible.';
 if(d.currency&&selected.data.currency&&d.currency!==selected.data.currency)return 'Application currency must match the linked call. Do not silently convert currencies.';
 if(d.requestedAmount!==null&&d.requestedAmount!==undefined&&d.requestedAmount!==''&&num(d.requestedAmount,-1)<0)return 'Requested amount must not be negative.';
 if(d.eligibilityDecision==='Eligible'){
 if(!complete)return 'Cannot approve eligibility from incomplete or inaccessible records.';
 const e=elig(d.opportunityId);if(!e.ready)return 'Mandatory eligibility checks must all be assessed Yes before human eligibility approval.';
 if(!str(d.reviewer).trim())return 'Record a named internal reviewer for the eligibility decision.';
 }
 if(['Submitted','Awarded','Declined'].includes(d.stage)&&(!dateOk(d.submittedAt)||day(d.submittedAt)>today))return 'Record a valid, already-completed submission date before setting Submitted or an outcome.';
 if(d.stage==='Awarded'&&(!complete||num(d.awardedAmount,0)<=0||!dateOk(d.awardDate)||!safeURL(d.awardNoticeUrl)))return 'Awarded requires complete authorized records, a positive verified amount, notification date, and official HTTPS award evidence.';
 }if(role==='milestones'){
 if(!str(d.title).trim()||!str(d.applicationId).trim()||!dateOk(d.due))return 'Provide task, linked application and due date.';
 if(d.status==='Done'&&(!dateOk(d.completedAt)||!str(d.evidence).trim()))return 'A completed task needs completion date and evidence.';
 }
