function submit(){const d=s.drawer;if(!d||d.type!=='edit'||!canWrite(d.role)){s.notice='No authorized write mapping is available.';return;}const meta=available[d.role],spec=fieldDefs[d.role];const initial=s.draft||{};const form=event.form&&typeof event.form==='object'?event.form:{};const data={...initial};for(const [id,,type] of spec){if(id==='archived'||!meta.writable.includes(id))continue;if(Object.prototype.hasOwnProperty.call(form,id))data[id]=form[id];if(!Object.prototype.hasOwnProperty.call(data,id))continue;const v=data[id];if(v!==null&&typeof v==='object'){s.notice='Use a scalar value for '+id;return;}if(type==='number'&&str(v)!==''&&!Number.isFinite(num(v,NaN))){s.notice='Enter a valid number for '+id;return;}data[id]=type==='number'?(str(v)===''?null:num(v)):type==='boolean'?yes(v):type==='date'?(str(v)||null):str(v);}
 s.draft=data;const prior=d.id?find(d.role,d.id):null;if(d.id&&(!prior||prior.version!==d.expectedVersion)){s.notice='Record version changed. Reopen it before saving; your draft is retained.';return;}
 const error=evidenceBlock(d.role,data,d.id)||validate(d.role,data,prior?.data||null);if(error){s.notice=error;s.draft=data;return;}
 const mapped={};for(const [id,physical] of Object.entries(meta.fields)){if(id==='archived')continue;if(!meta.writable.includes(id))continue;if(Object.prototype.hasOwnProperty.call(data,id))mapped[physical]=data[id];}
 if(!Object.keys(mapped).length){s.notice='None of the displayed fields are writable in the current binding.';return;}
 const change=prior?{kind:'update_record',typeId:meta.typeId,recordId:prior.id,expectedVersion:d.expectedVersion,data:mapped}:{kind:'create_record',typeId:meta.typeId,data:mapped};
 try{tools.call('records.propose',[change]);s.notice='Record change prepared for review — not yet saved.';}catch(e){s.notice='Review preparation failed. Your inputs were not saved: '+str(e.message||e).slice(0,160);s.draft=data;}
}
function archive(){const d=s.drawer;if(!d||d.type!=='archive'||!canWrite(d.role))return;const record=find(d.role,d.id);const m=available[d.role];if(record&&record.version!==d.expectedVersion){s.notice='Record version changed. Reopen archive.';return;}if(!record||archiveBlock(d.role,d.id)||!m.fields.archived||!m.writable.includes('archived')){s.notice='Archive is unavailable or there are linked records.';return;}
 try{tools.call('records.propose',[{kind:'update_record',typeId:m.typeId,recordId:record.id,expectedVersion:d.expectedVersion,data:{[m.fields.archived]:true}}]);s.drawer=null;s.notice='Archive prepared for review — nothing was deleted.';}catch(e){s.notice='Archive could not be prepared: '+str(e.message||e);}}
